mapper.select:
select l.loan_id, l.subject_id, l.item_name, l.item_type, l.asset_no, l.quantity, l.borrower_name, l.borrower_phone, l.borrower_org, l.borrower_remark, l.borrow_date, l.expected_return_date, l.actual_return_date, l.status, l.related_flow_id, l.voucher_object_id, l.note, l.create_by, l.create_time, l.update_by, l.update_time, l.deleted, s.name as subject_name from audit_loan l left join audit_subject s on l.subject_id = s.subject_id where l.deleted = 0 and s.name like concat('%', #{subjectName}, '%') and l.item_type = #{itemType} and l.status = #{status} and l.borrower_name like concat('%', #{borrowerName}, '%') and l.item_name like concat('%', #{itemName}, '%') and l.borrow_date >= #{beginTime} and l.borrow_date <= #{endTime}
and l.status in ('BORROWED', 'OVERDUE')
order by l.borrow_date desc, l.loan_id desc

mapper.update:
update audit_loan
subject_id = #{subjectId}, item_name = #{itemName}, item_type = #{itemType}, asset_no = #{assetNo}, quantity = #{quantity}, borrower_name = #{borrowerName}, borrower_phone = #{borrowerPhone}, borrower_org = #{borrowerOrg}, borrower_remark = #{borrowerRemark}, borrow_date = #{borrowDate}, expected_return_date = #{expectedReturnDate}, actual_return_date = #{actualReturnDate}, status = #{status}, related_flow_id = #{relatedFlowId}, voucher_object_id = #{voucherObjectId}, note = #{note}, deleted = #{deleted}, update_by = #{updateBy}, update_time = now()
where loan_id = #{loanId}
